const s=input.state,e=input.event,v=e.value;
function fmt(n){if(!isFinite(n))return '0';var r=Math.round(n*100)/100;return String(r);}
function recalc(){var o=s.originalServings>0?s.originalServings:1;var f=s.targetServings/o;s.factorText=fmt(f)+'\u00d7';s.hintText='Multiply every amount by '+fmt(f)+'.';s.ingredients.forEach(function(it){it.scaledText=fmt(it.amount*f)+(it.unit?' '+it.unit:'');});s.hasItems=s.ingredients.length>0;s.empty=!s.hasItems;}
if(e.type==='action'||e.type==='liveInput'){
 var a=e.actionId;
 if(a==='originalServings'){s.originalServings=Math.min(100,Math.max(1,Number(v)||1));}
 else if(a==='targetServings'){s.targetServings=Math.min(200,Math.max(1,Number(v)||1));}
 else if(a==='draftName'){s.draftName=String(v||'').slice(0,40);}
 else if(a==='draftUnit'){s.draftUnit=String(v||'').slice(0,16);}
 else if(a==='draftAmount'){var d=Number(v);if(isFinite(d))s.draftAmount=Math.min(100000,Math.max(0,d));}
 else if(a==='add'){var nm=s.draftName.trim();if(nm&&s.ingredients.length<30){s.ingredients.push({id:'i'+s.nextId,name:nm,amount:s.draftAmount,unit:s.draftUnit.trim(),scaledText:''});s.nextId=s.nextId+1;s.draftName='';}}
 else if(a==='amount'){var it=s.ingredients.filter(function(x){return x.id===v.key;})[0];if(it){var n=Number(v.value);if(isFinite(n))it.amount=Math.min(100000,Math.max(0,n));}}
 else if(a==='unit'){var it2=s.ingredients.filter(function(x){return x.id===v.key;})[0];if(it2)it2.unit=String(v.value||'').slice(0,16);}
 else if(a==='remove'){s.ingredients=s.ingredients.filter(function(x){return x.id!==v.key;});}
 else if(a==='reset'){s.originalServings=4;s.targetServings=6;s.ingredients=[{id:'i1',name:'Flour',amount:300,unit:'g',scaledText:''}];s.nextId=2;s.draftName='';s.draftAmount=100;s.draftUnit='g';}
 recalc();
}
return {state:s};
